from typing import List

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)

        # Coordinate compression
        vals = sorted(set(nums))
        rank = {v: i + 1 for i, v in enumerate(vals)}
        m = len(vals)

        cnt = [0] * (m + 2)
        sm = [0] * (m + 2)

        def update(i, val, delta):
            while i <= m:
                cnt[i] += delta
                sm[i] += val * delta
                i += i & -i

        def query_cnt(i):
            s = 0
            while i > 0:
                s += cnt[i]
                i -= i & -i
            return s

        def query_sm(i):
            s = 0
            while i > 0:
                s += sm[i]
                i -= i & -i
            return s

        # Largest power of 2 <= m
        LOG = 1 << (m.bit_length() - 1) if m > 0 else 0

        def find_kth(kk):
            i = 0
            bit = LOG
            remaining = kk
            while bit > 0:
                if i + bit <= m and cnt[i + bit] < remaining:
                    remaining -= cnt[i + bit]
                    i += bit
                bit //= 2
            return i + 1

        costs = []
        total_sum = 0
        mid_pos = (x + 1) // 2  # 1-indexed median position

        for i in range(n):
            r = rank[nums[i]]
            update(r, nums[i], 1)
            total_sum += nums[i]

            if i >= x:
                ro = rank[nums[i - x]]
                update(ro, nums[i - x], -1)
                total_sum -= nums[i - x]

            if i >= x - 1:
                mr = find_kth(mid_pos)
                median = vals[mr - 1]
                lower_sum = query_sm(mr - 1)
                lower_cnt = query_cnt(mr - 1)
                cost = (median * lower_cnt - lower_sum
                        + (total_sum - lower_sum) - median * (x - lower_cnt))
                costs.append(cost)

        # DP
        INF = float('inf')
        dp = [[INF] * (k + 1) for _ in range(n + 1)]
        for p in range(n + 1):
            dp[p][0] = 0

        for p in range(1, n + 1):
            dp_p = dp[p]
            dp_p_minus_1 = dp[p - 1]

            # Optimization: can't place more subarrays than length allows
            max_j = p // x
            if max_j > k:
                max_j = k

            for j in range(1, max_j + 1):
                dp_p[j] = dp_p_minus_1[j]

            if p >= x:
                dp_p_minus_x = dp[p - x]
                cost = costs[p - x]
                for j in range(1, max_j + 1):
                    cand = dp_p_minus_x[j - 1] + cost
                    if cand < dp_p[j]:
                        dp_p[j] = cand

        return dp[n][k]
